// Extrait le JSON renvoyé par Claude et le normalise pour le dashboard
const content = $input.first().json.content?.[0]?.text || '{}';
let r;
try { const m = content.match(/\{[\s\S]*\}/); r = JSON.parse(m ? m[0] : content); }
catch(e){ r = { score:0, direction:'NEUTRAL', ai_analysis:'parse error: '+content.substring(0,150) }; }
return [{ json: r }];
